from pathlib import Path
p=Path('market.js'); s=p.read_text()
anchor='  function portfolioIntelligence(rows,total){\n'
if anchor not in s: raise SystemExit('portfolioIntelligence anchor missing')
insert='''  function renderPortfolioDecisionCenter(rows,total){\n    const analysed=rows.reduce((a,r)=>a+(n(r.value)||0),0)||1;\n    const ranked=rows.map(r=>({...r,conviction:portfolioConviction(r.stock)}));\n    const convRows=ranked.filter(r=>r.conviction!=null&&r.value>0);\n    const convWeight=convRows.reduce((a,r)=>a+r.value,0)||1;\n    const conviction=convRows.reduce((a,r)=>a+r.value*r.conviction,0)/convWeight;\n    const targets=loadPortfolioTargets();\n    const riskBudget=renderRiskBudget(ranked);\n    const stresses=Object.keys(PORTFOLIO_STRESS_SCENARIOS).map(k=>portfolioStress(ranked,k)).sort((a,b)=>a.resilience-b.resilience);\n    const worst=stresses[0];\n    const sectors=new Map(); ranked.forEach(r=>{const k=txt(r.stock.sector)||'Sem setor'; sectors.set(k,(sectors.get(k)||0)+r.value)});\n    const topSector=[...sectors.entries()].map(([name,value])=>({name,pct:value/analysed*100})).sort((a,b)=>b.pct-a.pct)[0];\n    const topPosition=ranked.slice().sort((a,b)=>b.value-a.value)[0];\n    const topPositionPct=topPosition?topPosition.value/analysed*100:0;\n    const review=ranked.filter(r=>['high','severe'].includes(txt(r.stock.risk_gate))||txt(r.stock.thesis_direction)==='down'||txt(r.stock.estimate_signal)==='deteriorating'||(r.conviction!=null&&r.conviction<50)).sort((a,b)=>(a.conviction??999)-(b.conviction??999));\n    const reinforce=ranked.filter(r=>r.conviction!=null&&r.conviction>=70&&n(r.stock.confidence_score)>=60&&!['high','severe'].includes(txt(r.stock.risk_gate))&&!['overvalued','uncertain'].includes(txt(r.stock.valuation_signal))&&txt(r.stock.estimate_signal)!=='deteriorating').sort((a,b)=>b.conviction-a.conviction);\n    let health=100; health-=Math.max(0,topPositionPct-targets.maxPosition)*1.4; health-=Math.max(0,(topSector?.pct||0)-targets.maxSector)*1.1; health-=review.length*2.2; health-=(100-riskBudget.fit)*.25; health-=(100-(worst?.resilience||100))*.20; health=Math.max(0,Math.min(100,Math.round(health)));\n    const tone=health>=80?'is-positive':health>=60?'is-warn':'is-risk';\n    const priorities=[];\n    if(review[0]) priorities.push(`Rever ${review[0].stock.ticker}: ${review[0].conviction==null?'convicção insuficiente':`convicção ${Math.round(review[0].conviction)}/100`}`);\n    if(topPositionPct>targets.maxPosition&&topPosition) priorities.push(`${topPosition.stock.ticker} está acima do objetivo por posição (${topPositionPct.toFixed(1)}%)`);\n    if(topSector&&topSector.pct>targets.maxSector) priorities.push(`${topSector.name} está acima do objetivo setorial (${topSector.pct.toFixed(1)}%)`);\n    if(worst&&worst.resilience<70) priorities.push(`Stress mais exigente: ${PORTFOLIO_STRESS_SCENARIOS[worst.key].label} · resiliência ${worst.resilience}/100`);\n    if(!priorities.length&&reinforce[0]) priorities.push(`Carteira sem alerta dominante; ${reinforce[0].stock.ticker} é o reforço com maior convicção atual`);\n    const next=review[0]?`Abrir ${review[0].stock.ticker} e rever a tese`:topPositionPct>targets.maxPosition?'Usar o Rebalancer para reduzir concentração':reinforce[0]?`Avaliar reforço em ${reinforce[0].stock.ticker}`:'Manter e acompanhar';\n    return `<div class="market-detail-card market-decision-center"><div class="market-perspective-head"><div><small>PORTFOLIO DECISION CENTER</small><h4>O que merece atenção agora?</h4></div><span class="market-target-fit-score ${tone}">${health}/100</span></div><div class="market-decision-kpis"><div><small>Convicção</small><strong>${conviction.toFixed(1)}</strong></div><div><small>Risk Budget</small><strong>${riskBudget.fit}</strong></div><div><small>Pior stress</small><strong>${worst?worst.resilience:'—'}</strong></div><div><small>Rever/Substituir</small><strong>${review.length}</strong></div></div><div class="market-decision-next"><small>PRÓXIMA AÇÃO DE RESEARCH</small><strong>${esc(next)}</strong></div><ul class="market-case-list">${priorities.slice(0,4).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="market-case-note">Síntese executiva: agrega sinais já existentes e não cria um novo score de investimento.</p></div>`;\n  }\n\n'''
s=s.replace(anchor,insert+anchor,1)
needle='    return `<div class="market-detail-card"><div class="market-perspective-head"><div><small>PORTFOLIO INTELLIGENCE</small>'
if needle not in s: raise SystemExit('portfolio return anchor missing')
s=s.replace(needle,'    return `${renderPortfolioDecisionCenter(rows,total)}\n      <div class="market-detail-card"><div class="market-perspective-head"><div><small>PORTFOLIO INTELLIGENCE</small>',1)
p.write_text(s)
p=Path('market.css'); s=p.read_text(); s+='''\n/* v6.0 Portfolio Decision Center */\n.market-decision-center{border-color:rgba(17,55,69,.22)}\n.market-decision-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:12px 0}\n.market-decision-kpis>div{padding:10px;border:1px solid rgba(17,55,69,.12);border-radius:14px;background:rgba(255,255,255,.35)}\n.market-decision-kpis small{display:block;font-size:10px;letter-spacing:.05em;text-transform:uppercase}.market-decision-kpis strong{display:block;margin-top:3px;font-size:18px}\n.market-decision-next{padding:12px 14px;border-radius:14px;background:rgba(17,55,69,.06);margin:10px 0}.market-decision-next small{display:block;font-size:10px;letter-spacing:.08em}.market-decision-next strong{display:block;margin-top:4px}\n@media(max-width:620px){.market-decision-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}\n'''; p.write_text(s)
p=Path('README.md'); s=p.read_text(); p.write_text('''## Vestra v6.0 — Portfolio Decision Center\n\n- Nova síntese executiva no topo de As minhas posições.\n- Consolida convicção ponderada, Risk Budget, pior Stress Test, concentração e posições a rever.\n- Mostra prioridades e uma próxima ação de research sem criar um novo score de investimento.\n- Mantém Action Map, Targets, Stress Test, Fresh Capital Planner e Rebalancer abaixo para detalhe.\n- PWA cache: `vestra-cache-v56`.\n\n'''+s)
